"""Regular-language objects, pattern parsing and matching.

Patterns follow the documented Eywa grammar: a union of sequences, where a
sequence is zero or more atoms and an atom carries zero or more postfix ``*``
repetitions.  Atoms are literals, groups or non-empty character classes.
Matching is performed over Latin-1 code points with a Thompson NFA simulation,
so arbitrary nested/nullable repetitions are handled without backtracking.
"""

class RegexError(Exception):
    """Raised when a pattern does not follow the documented grammar."""


class Regex(object):
    """A regular expression node; compiled lazily to an NFA for matching."""

    def __init__(self):
        self._nfa = None


class Empty(Regex):
    """A regular expression that matches the empty string."""

    def __str__(self):
        return ""


class Range(Regex):
    """A regular expression that matches one character range."""

    def __init__(self, low, high):
        Regex.__init__(self)
        if len(low) != 1 or len(high) != 1:
            raise RegexError("Range must be single characters")
        self.low = low
        self.high = high

    def __str__(self):
        return "[%s-%s]" % (self.low, self.high)


class Class(Regex):
    """A regular expression that matches one character of a set of ranges."""

    def __init__(self, items):
        Regex.__init__(self)
        self.items = tuple(items)

    def __str__(self):
        return "[" + ",".join(
            "%s-%s" % (chr(low), chr(high)) for (low, high) in self.items) + "]"


class Choice(Regex):
    """A regular expression that matches a choice of regular expressions."""

    def __init__(self, *args):
        Regex.__init__(self)
        self.exprs = list(args)

    def __str__(self):
        return "(" + "|".join(str(e) for e in self.exprs) + ")"


class Seq(Regex):
    """A regular expression that matches a sequence of regular expressions."""

    def __init__(self, *args):
        Regex.__init__(self)
        self.exprs = list(args)

    def __str__(self):
        return "(" + "".join(str(e) for e in self.exprs) + ")"


class Star(Regex):
    """A regular expression that matches zero or more iterations."""

    def __init__(self, r):
        Regex.__init__(self)
        self.expr = r

    def __str__(self):
        return "(" + str(self.expr) + ")*"


def chars(low, high):
    """A regular expression that matches a character range."""
    return Range(low, high)


def empty():
    """A regular expression that matches the empty string."""
    return Empty()


def text(s):
    """A regular expression that matches an exact string."""
    if s == "":
        return empty()
    if len(s) == 1:
        return chars(s, s)
    return seq(*[chars(c, c) for c in s])


def choice(*args):
    return Choice(*args)


def seq(*args):
    return Seq(*args)


def star(r):
    return Star(r)


def plus(r):
    return seq(r, star(r))


_SYMBOLS = frozenset("()[]|\*")


def parse(pattern):
    """Parse a documented pattern into a regular-expression object."""
    if not isinstance(pattern, str):
        raise RegexError("pattern must be a string")
    data = pattern
    size = len(data)
    pos = 0

    def fail(reason):
        raise RegexError("%s at offset %d" % (reason, pos))

    def parse_union():
        nonlocal pos
        alts = [parse_seq()]
        while pos < size and data[pos] == "|":
            pos += 1
            alts.append(parse_seq())
        if len(alts) == 1:
            return alts[0]
        return Choice(*alts)

    def parse_seq():
        nonlocal pos
        items = []
        while pos < size and data[pos] != "|" and data[pos] != ")":
            items.append(parse_atom())
        if not items:
            return Empty()
        if len(items) == 1:
            return items[0]
        return Seq(*items)

    def parse_atom():
        nonlocal pos
        node = parse_primary()
        while pos < size and data[pos] == "*":
            pos += 1
            node = Star(node)
        return node

    def escaped():
        nonlocal pos
        pos += 1
        if pos >= size:
            fail("dangling escape")
        char = data[pos]
        pos += 1
        return char

    def parse_primary():
        nonlocal pos
        if pos >= size:
            fail("truncated pattern")
        char = data[pos]
        if char == "(":
            pos += 1
            node = parse_union()
            if pos >= size or data[pos] != ")":
                fail("unclosed group")
            pos += 1
            return node
        if char == "[":
            return parse_class()
        if char == "*":
            fail("repetition without an atom")
        if char == ")":
            fail("unbalanced group")
        if char == "]":
            fail("unbalanced class")
        if char == "|":
            fail("empty alternative")
        if char == "\\":
            return Range(escaped(), escaped.__self__ if False else _last[0])
        pos += 1
        return Range(char, char)

    def parse_class():
        nonlocal pos
        pos += 1
        items = []
        while True:
            if pos >= size:
                fail("unclosed class")
            char = data[pos]
            if char == "]":
                pos += 1
                break
            if char == "\\":
                low = escaped()
            else:
                low = char
                pos += 1
            if (pos + 1 < size and data[pos] == "-" and data[pos + 1] != "]"):
                pos += 1
                if data[pos] == "\\":
                    high = escaped()
                else:
                    high = data[pos]
                    pos += 1
                items.append((ord(low), ord(high)))
            else:
                items.append((ord(low), ord(low)))
        if not items:
            fail("empty class")
        items.sort()
        merged = []
        for low, high in items:
            if low > high:
                continue
            if merged and low <= merged[-1][1] + 1:
                if high > merged[-1][1]:
                    merged[-1] = (merged[-1][0], high)
            else:
                merged.append((low, high))
        return Class(merged)

    _last = [None]
    try:
        node = parse_union()
    except RecursionError:
        raise RegexError("pattern nesting too deep")
    if pos != size:
        fail("unexpected trailing input")
    return node
PYEOF
